  1	import java.io.PrintStream;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	
  6	final class MST {
  7	    private static final int NO_EDGE = 0;
  8	    private static final int ROOT_PARENT = -1;
  9	    private static final int START_VERTEX = 0;
 10	
 11	    private MST() {}
 12	
 13	    record Edge(int from, int to, int weight) {}
 14	
 15	    record Result(List<Edge> edges, int totalWeight) {
 16	        Result {
 17	            edges = List.copyOf(edges);
 18	        }
 19	    }
 20	
 21	    private static final class PrimState {
 22	        final int[] parent;
 23	        final int[] bestEdgeWeight;
 24	        final boolean[] includedInMst;
 25	
 26	        PrimState(int vertexCount) {
 27	            this.parent = new int[vertexCount];
 28	            this.bestEdgeWeight = new int[vertexCount];
 29	            this.includedInMst = new boolean[vertexCount];
 30	            Arrays.fill(bestEdgeWeight, Integer.MAX_VALUE);
 31	            bestEdgeWeight[START_VERTEX] = 0;
 32	            parent[START_VERTEX] = ROOT_PARENT;
 33	        }
 34	    }
 35	
 36	    private static int selectNextVertex(PrimState state) {
 37	        int minValue = Integer.MAX_VALUE;
 38	        int minIndex = -1;
 39	
 40	        for (int vertex = 0; vertex < state.includedInMst.length; vertex++) {
 41	            if (!state.includedInMst[vertex] && state.bestEdgeWeight[vertex] < minValue) {
 42	                minValue = state.bestEdgeWeight[vertex];
 43	                minIndex = vertex;
 44	            }
 45	        }
 46	
 47	        return minIndex;
 48	    }
 49	
 50	    private static void validateGraph(int[][] graph) {
 51	        if (graph == null) {
 52	            throw new IllegalArgumentException("Graph must not be null.");
 53	        }
 54	
 55	        if (graph.length == 0) {
 56	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
 57	        }
 58	
 59	        for (int rowIndex = 0; rowIndex < graph.length; rowIndex++) {
 60	            int[] row = graph[rowIndex];
 61	            if (row == null) {
 62	                throw new IllegalArgumentException("Graph rows must not be null.");
 63	            }
 64	
 65	            if (row.length != graph.length) {
 66	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
 67	            }
 68	
 69	            for (int columnIndex = rowIndex + 1; columnIndex < graph.length; columnIndex++) {
 70	                if (row[columnIndex] != graph[columnIndex][rowIndex]) {
 71	                    throw new IllegalArgumentException(
 72	                        "Graph must represent an undirected adjacency matrix."
 73	                    );
 74	                }
 75	            }
 76	        }
 77	    }
 78	
 79	    private static Result buildResult(PrimState state, int[][] graph) {
 80	        List<Edge> edges = new ArrayList<>();
 81	        int totalWeight = 0;
 82	
 83	        for (int vertex = 1; vertex < graph.length; vertex++) {
 84	            int from = state.parent[vertex];
 85	            int weight = graph[from][vertex];
 86	
 87	            edges.add(new Edge(from, vertex, weight));
 88	            totalWeight += weight;
 89	        }
 90	
 91	        return new Result(edges, totalWeight);
 92	    }
 93	
 94	    private static void relaxOutgoingEdges(int[][] graph, PrimState state, int currentVertex) {
 95	        state.includedInMst[currentVertex] = true;
 96	
 97	        for (int neighbor = 0; neighbor < graph.length; neighbor++) {
 98	            int edgeWeight = graph[currentVertex][neighbor];
 99	
100	            if (edgeWeight != NO_EDGE && !state.includedInMst[neighbor]
101	                && edgeWeight < state.bestEdgeWeight[neighbor]) {
102	                state.parent[neighbor] = currentVertex;
103	                state.bestEdgeWeight[neighbor] = edgeWeight;
104	            }
105	        }
106	    }
107	
108	    static Result computeMinimumSpanningTree(int[][] graph) {
109	        validateGraph(graph);
110	
111	        int vertexCount = graph.length;
112	        PrimState state = new PrimState(vertexCount);
113	
114	        for (int count = 0; count < vertexCount - 1; count++) {
115	            int currentVertex = selectNextVertex(state);
116	
117	            if (currentVertex == -1) {
118	                throw new IllegalStateException("Graph must be connected.");
119	            }
120	
121	            relaxOutgoingEdges(graph, state, currentVertex);
122	        }
123	
124	        return buildResult(state, graph);
125	    }
126	
127	    static String renderResult(Result result) {
128	        StringBuilder output = new StringBuilder("Edge \tWeight\n");
129	        for (Edge edge : result.edges()) {
130	            output.append(edge.from())
131	                .append(" - ")
132	                .append(edge.to())
133	                .append('\t')
134	                .append(edge.weight())
135	                .append('\n');
136	        }
137	        return output.toString();
138	    }
139	
140	    static void printResult(PrintStream out, Result result) {
141	        out.print(renderResult(result));
142	    }
143	
144	    public static void main(String[] args)
145	    {
146	        int graph[][] = new int[][] { { 0, 2, 0, 6, 0 },
147	                                      { 2, 0, 3, 8, 5 },
148	                                      { 0, 3, 0, 0, 7 },
149	                                      { 6, 8, 0, 0, 9 },
150	                                      { 0, 5, 7, 9, 0 } };
151	
152	        Result result = computeMinimumSpanningTree(graph);
153	        printResult(System.out, result);
154	    }
155	}
